 4	/** Format integer cents as a fixed 2-decimal string, e.g. 1005 -> "10.05". */
 5	export function formatCents(cents: number): string {
 6	  if (!Number.isInteger(cents)) {
 7	    throw new Error(`formatCents expects an integer number of cents, got ${cents}`);
 8	  }
 9	  const sign = cents < 0 ? "-" : "";
10	  const abs = Math.abs(cents);
11	  const whole = Math.floor(abs / 100);
12	  const frac = String(abs % 100).padStart(2, "0");
13	  return `${sign}${whole}.${frac}`;
14	}
15	
16	/** Parse a decimal amount string ("10.05") into integer cents (1005). */
17	export function parseCents(input: string): number {
18	  const trimmed = input.trim();
19	  const match = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(trimmed);
20	  if (!match) {
21	    throw new Error(`invalid amount: ${input}`);
22	  }
23	  const [, sign, whole, frac = ""] = match;
24	  const paddedFrac = frac.padEnd(2, "0");
25	  const cents = Number(whole) * 100 + Number(paddedFrac);
26	  return sign === "-" ? -cents : cents;
27	}
